import{_ as o,c as e,o as a,a3 as r}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Customization","description":"","frontmatter":{},"headers":[],"relativePath":"guide/customize.md","filePath":"guide/customize.md","lastUpdated":1785933680000}'),n={name:"guide/customize.md"};function i(s,t,l,d,c,u){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="customization" tabindex="-1">Customization <a class="header-anchor" href="#customization" aria-label="Permalink to &quot;Customization&quot;">​</a></h1><p>Make ClipboardxAI work the way you do. This guide covers the settings you can adjust.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>Open <strong>ClipboardxAI → Settings</strong> (or press <code>Cmd+,</code>).</p><ul><li><strong>Language</strong>: English, 简体中文, 繁體中文, 日本語.</li><li><strong>Launch at Login</strong>: start the app automatically when you log in.</li><li><strong>Appearance</strong>: Light, Dark, or System (follows macOS).</li></ul><h2 id="ai-configuration" tabindex="-1">AI Configuration <a class="header-anchor" href="#ai-configuration" aria-label="Permalink to &quot;AI Configuration&quot;">​</a></h2><p>Set up cloud AI in <strong>Settings → AI</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th><th>Description</th></tr></thead><tbody><tr><td><strong>Provider</strong></td><td>DeepSeek, MiniMax, GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic, Gemini</td><td>The OpenAI-compatible service to call</td></tr><tr><td><strong>API Key</strong></td><td>your key</td><td>Stored in the <strong>Keychain</strong>, never written to disk in plain text</td></tr><tr><td><strong>Model</strong></td><td>per provider</td><td>The model used for AI actions</td></tr><tr><td><strong>Cloud AI enabled</strong></td><td>On / Off</td><td>Master switch for sending clips to the cloud</td></tr></tbody></table><p>Cloud AI is <strong>off by default</strong>. When enabled, your clip is sent only to the provider you configured.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p>Customize how tools behave:</p><ul><li><strong>Auto-run on output</strong>: when on, the selected tool runs automatically the moment you copy.</li><li><strong>Excluded apps</strong>: apps listed here are skipped by clipboard monitoring and auto-run (e.g. password managers).</li><li><strong>Tool order</strong>: in the AI Tool window, drag installed tools to reorder them; your order is remembered.</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Open <strong>Settings → Privacy</strong>:</p><ul><li><strong>Cloud AI opt-in</strong>: the master switch for sending data to a provider.</li><li><strong>Excluded apps</strong>: stop specific apps from being captured.</li><li><strong>History controls</strong>: manage how long clips are kept on your device.</li></ul><p>All history stays local. We do not upload clips or run analytics.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>Manage installed actions:</p><ul><li><strong>Browse</strong>: open <strong>Marketplace</strong> from the AI Tool window or the site.</li><li><strong>Install</strong>: click <strong>Install</strong> on an action to add it via deep link.</li><li><strong>Remove</strong>: uninstall an action from your <strong>Installed</strong> list.</li></ul><h2 id="menu-bar" tabindex="-1">Menu Bar <a class="header-anchor" href="#menu-bar" aria-label="Permalink to &quot;Menu Bar&quot;">​</a></h2><ul><li><strong>Show in menu bar</strong>: enable/disable the tray icon.</li><li><strong>Quit on close</strong>: choose whether the app stays running in the background.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Keep cloud AI off until you need it — local tools cover most day-to-day cleanup.</li><li>Add password managers and secure-input apps to <strong>Excluded apps</strong> so secrets are never captured.</li><li>Pair auto-run with a local tool for hands-free text cleanup on every copy.</li></ul>',23)])])}const h=o(n,[["render",i]]);export{g as __pageData,h as default};
